+  for (int i = 0; i < 16; ++i) {
+    const uint64_t* xmm = (const uint64_t*)&uc->uc_mcontext.fpregs->_xmm[i];
+    uint64_t values[4] = {xmm[0], xmm[1], 0, 0};
+    if (has_ymm_hi128) {
+      const uint64_t* ymmh = (const uint64_t*)(xsave + XSAVE_HDR_OFFSET + XSAVE_HDR_SIZE + (i * 16));
+      values[2] = ymmh[0];
+      values[3] = ymmh[1];
