+            Pattern[] ymmPatterns = createRegisterPatterns("YMM", 16);
+            Pattern[] ymmNegativePatterns = new Pattern[] {
+                Pattern.compile("XMM\\[.*\\]=.*"),
+            };
+            HsErrFileUtils.checkHsErrFileContent(hsErrFile, ymmPatterns, ymmNegativePatterns, false, false);
